package com.lamggm.rospocket;
import org.json.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=31)
public class CardNamesCodecTest {
 static JSONObject named()throws Exception{JSONObject j=new JSONObject(DashboardLayout.defaults().encode()).put("schema",3);j.remove("columns");j.getJSONArray("cards").remove(7);JSONArray a=j.getJSONArray("cards");for(int i=0;i<a.length();i++){a.getJSONObject(i).remove("column");a.getJSONObject(i).remove("row");}for(int i=0;i<a.length();i++)a.getJSONObject(i).put("name",i==0?"Velocidade":i==4?"Modelo frontal":"");return LegacyCodecFixtures.layout(j);}
 static String name(DashboardLayout l,String id)throws Exception{JSONArray a=new JSONObject(l.encode()).getJSONArray("cards");for(int i=0;i<a.length();i++)if(a.getJSONObject(i).getString("id").equals(id))return a.getJSONObject(i).getString("name");throw new AssertionError();}
 @Test public void manualNamesSurviveCodecResizeOrderAndDisplayChanges()throws Exception{DashboardLayout l=DashboardLayout.decode(named().toString()).resize("watch0",2,1).before("robot","watch0").display("watch0",new DashboardLayout.Display("gauge","data",0,100,"m/s"));assertEquals("Velocidade",name(l,"watch0"));assertEquals("Modelo frontal",name(l,"robot"));assertEquals(l.encode(),DashboardLayout.decode(l.encode()).encode());}
 @Test public void legacySchemasMigrateInMemoryAndInvalidNamesAreRejected()throws Exception{for(int s:new int[]{1,2}){JSONObject j=new JSONObject(DashboardLayout.defaults().encode()).put("schema",s);j.remove("columns");j.getJSONArray("cards").remove(7);for(int i=0;i<7;i++){JSONObject r=j.getJSONArray("cards").getJSONObject(i);r.remove("column");r.remove("row");r.remove("name");if(s==1)r.remove("display");}assertEquals("",name(DashboardLayout.decode(LegacyCodecFixtures.layout(j).toString()),"watch0"));}for(Object bad:new Object[]{false,JSONObject.NULL,"x\ny","x".repeat(65)}){JSONObject j=named();j.getJSONArray("cards").getJSONObject(0).put("name",bad);assertThrows(IllegalArgumentException.class,()->DashboardLayout.decode(LegacyCodecFixtures.layout(j).toString()));}}
}
